-- Profile posts and safe public feed
-- Applied to Supabase project khzqerdrhzdrkhdxfaxn on 2026-11-02.
create table if not exists bc_private.profile_posts (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.bc_profiles(id) on delete cascade, body text not null check (length(btrim(body)) between 1 and 1200), tags text[] not null default '{}'::text[] check (cardinality(tags) <= 5), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table bc_private.profile_posts enable row level security;
revoke all on table bc_private.profile_posts from anon, authenticated;
create index if not exists profile_posts_author_created_idx on bc_private.profile_posts (author_id, created_at desc);
create or replace function public.bc_list_public_profile_posts(p_author uuid default null, p_limit integer default 100) returns table (id uuid, author_id uuid, body text, tags text[], created_at timestamptz, updated_at timestamptz) language sql stable security definer set search_path = pg_catalog, bc_private, public as $$ select pp.id,pp.author_id,pp.body,pp.tags,pp.created_at,pp.updated_at from bc_private.profile_posts pp join public.bc_profiles p on p.id=pp.author_id where p.is_blocked is not true and (p_author is null or pp.author_id=p_author) order by pp.created_at desc limit greatest(1,least(coalesce(p_limit,100),100)); $$;
create or replace function public.bc_create_profile_post(p_body text,p_tags text[] default '{}'::text[]) returns table (id uuid,author_id uuid,body text,tags text[],created_at timestamptz,updated_at timestamptz) language plpgsql security definer set search_path = pg_catalog, bc_private, public as $$ declare v_user uuid:=auth.uid();v_post bc_private.profile_posts;v_tags text[]; begin if v_user is null then raise exception 'Please sign in to publish a post.';end if;if not exists(select 1 from public.bc_profiles where id=v_user and is_blocked is not true)then raise exception 'Create an active business profile before publishing.';end if;if length(btrim(coalesce(p_body,''))) not between 1 and 1200 then raise exception 'Your post must be between 1 and 1,200 characters.';end if;select coalesce(array_agg(tag),'{}'::text[]) into v_tags from(select distinct left(btrim(value),40) tag from unnest(coalesce(p_tags,'{}'::text[])) value where length(btrim(value))>0 limit 5) clean;insert into bc_private.profile_posts(author_id,body,tags)values(v_user,btrim(p_body),v_tags)returning * into v_post;return query select v_post.id,v_post.author_id,v_post.body,v_post.tags,v_post.created_at,v_post.updated_at;end;$$;
create or replace function public.bc_delete_own_profile_post(p_post uuid) returns boolean language plpgsql security definer set search_path = pg_catalog, bc_private, public as $$ begin if auth.uid() is null then raise exception 'Please sign in.';end if;delete from bc_private.profile_posts where id=p_post and author_id=auth.uid();if not found then raise exception 'Post not found or you do not have permission to delete it.';end if;return true;end;$$;
revoke all on function public.bc_list_public_profile_posts(uuid,integer) from public; revoke all on function public.bc_create_profile_post(text,text[]) from public; revoke all on function public.bc_delete_own_profile_post(uuid) from public; grant execute on function public.bc_list_public_profile_posts(uuid,integer) to anon,authenticated; grant execute on function public.bc_create_profile_post(text,text[]) to authenticated; grant execute on function public.bc_delete_own_profile_post(uuid) to authenticated;